import pytest

from linfw.demo import DemoRunner
from linfw.firewall import Firewall
from linfw.model import FirewallError, NewRule
from linfw.parser import parse_save

SAVE = """\
# Generated by iptables-save
*filter
:INPUT DROP [5:300]
:FORWARD ACCEPT [0:0]
:OUTPUT ACCEPT [0:0]
:DOCKER-USER - [0:0]
:LINFW_OFF_DROP - [0:0]
[10:840] -A INPUT -i lo -j ACCEPT
[7:500] -A INPUT -p tcp -m tcp --dport 22 -j ACCEPT
[0:0] -A INPUT -p tcp -m multiport --dports 80,443 -s 10.0.0.1/32 -m comment --comment "web ui" -j LINFW_OFF_DROP
[3:120] -A INPUT ! -s 1.2.3.4/32 -p udp --sport 53 -j REJECT --reject-with icmp-port-unreachable
[1:1] -A FORWARD -j DOCKER-USER
[2:2] -A DOCKER-USER -j RETURN
COMMIT
"""


def test_parse_columns():
    snap = parse_save(SAVE)
    assert snap.policies == {"INPUT": "DROP", "FORWARD": "ACCEPT", "OUTPUT": "ACCEPT"}
    lo, ssh, web, udp = snap.rules["INPUT"]
    assert (lo.index, lo.pkts, lo.action, lo.extra) == (1, 10, "accept", ("-i", "lo"))
    assert (ssh.protocol, ssh.port, ssh.extra) == ("tcp", "22", ())
    assert (web.port, web.source, web.enabled, web.action) == ("80,443", "10.0.0.1", False, "drop")
    assert web.extra == ("-m", "comment", "--comment", "web ui")
    assert (udp.source, udp.port, udp.action) == ("!1.2.3.4", "sp:53", "reject")
    assert snap.rules["FORWARD"][0].action == "docker-user"
    assert "LINFW_OFF_DROP" in snap.chains


@pytest.mark.parametrize(
    "kwargs, spec",
    [
        (dict(), ["-j", "ACCEPT"]),
        (dict(protocol="tcp", port="22"), ["-p", "tcp", "--dport", "22", "-j", "ACCEPT"]),
        (
            dict(protocol="udp", port="80, 443", source="10.0.0.0/8", destination="1.1.1.1", action="DROP"),
            ["-p", "udp", "-s", "10.0.0.0/8", "-d", "1.1.1.1", "-m", "multiport", "--dports", "80,443", "-j", "DROP"],
        ),
        (dict(protocol="tcp", port="1000-2000"), ["-p", "tcp", "--dport", "1000:2000", "-j", "ACCEPT"]),
    ],
)
def test_new_rule_spec(kwargs, spec):
    assert NewRule(**kwargs).validated().to_spec() == spec


@pytest.mark.parametrize(
    "kwargs",
    [
        dict(protocol="icmp", port="22"),
        dict(protocol="all", port="22"),
        dict(protocol="tcp", port="70000"),
        dict(protocol="tcp", port="abc"),
        dict(protocol="tcp", port="9:1"),
        dict(source="example.com"),
        dict(destination="10.0.0.0/33"),
    ],
)
def test_new_rule_invalid(kwargs):
    with pytest.raises(ValueError):
        NewRule(**kwargs).validated()


@pytest.fixture
def fw():
    return Firewall(DemoRunner(jitter=False))


def actions(fw, chain):
    return [(r.action, r.enabled) for r in fw.snapshot().rules[chain]]


def test_add_goes_before_catch_all_deny(fw):
    before = len(fw.snapshot().rules["INPUT"])
    fw.add(NewRule("INPUT", "tcp", "ACCEPT", port="8080"))
    rules = fw.snapshot().rules["INPUT"]
    assert len(rules) == before + 1
    assert rules[-2].port == "8080" and rules[-1].is_catch_all_deny


def test_add_appends_when_chain_has_no_catch_all_deny(fw):
    # OUTPUT ends with "-j ACCEPT", which is not a deny rule: append at the end
    fw.add(NewRule("OUTPUT", "tcp", "DROP", port="25"))
    assert fw.snapshot().rules["OUTPUT"][-1].port == "25"


def test_catch_all_deny_is_appended_last(fw):
    fw.add(NewRule("INPUT", "all", "REJECT"))
    assert fw.snapshot().rules["INPUT"][-1].action == "reject"


def test_delete_and_stale_rule(fw):
    snap = fw.snapshot()
    victim, other = snap.rules["INPUT"][2], snap.rules["INPUT"][0]
    fw.delete(victim)
    assert len(fw.snapshot().rules["INPUT"]) == len(snap.rules["INPUT"]) - 1
    with pytest.raises(FirewallError):
        fw.delete(victim)  # the chain shifted, the old view is stale
    fw.delete(other)


def test_move_keeps_counters_and_edges(fw):
    rules = fw.snapshot().rules["INPUT"]
    ssh = rules[2]
    assert fw.move(ssh, -1)
    moved = fw.snapshot().rules["INPUT"]
    assert moved[1].spec == ssh.spec and moved[1].pkts == ssh.pkts
    assert len(moved) == len(rules)
    assert fw.move(moved[1], 1)
    assert [r.spec for r in fw.snapshot().rules["INPUT"]] == [r.spec for r in rules]
    assert not fw.move(fw.snapshot().rules["INPUT"][0], -1)
    assert not fw.move(fw.snapshot().rules["INPUT"][-1], 1)


def test_move_down_to_last_position(fw):
    rules = fw.snapshot().rules["FORWARD"]
    assert fw.move(rules[0], 1)
    assert fw.snapshot().rules["FORWARD"][-1].spec == rules[0].spec


def test_toggle_roundtrip(fw):
    reject = next(r for r in fw.snapshot().rules["INPUT"] if r.action == "reject")
    assert fw.toggle(reject) is False
    off = fw.snapshot().rules["INPUT"][reject.index - 1]
    assert (off.enabled, off.action) == (False, "reject")
    assert "--reject-with" not in off.spec
    assert off.pkts == reject.pkts
    assert fw.toggle(off) is True
    on = fw.snapshot().rules["INPUT"][reject.index - 1]
    assert (on.enabled, on.action) == (True, "reject")


def test_toggle_unsupported_target():
    runner = DemoRunner(sample=False)
    runner.rules["FORWARD"].append([0, 0, ["-j", "DOCKER-USER"]])
    fw = Firewall(runner)
    with pytest.raises(FirewallError):
        fw.toggle(fw.snapshot().rules["FORWARD"][0])
